inflight = {}
def get(key):
    v = l1.get(key)
    if v: return v
    if key in inflight: return inflight[key].wait()
    fut = inflight[key] = Future()
    try:
        v = l2.get(key) or db.load(key)
        l1.put(key, v, ttl=jitter(30s, 20%))
        fut.set(v); return v
    finally:
        del inflight[key]

W = {'view': 1, 'cart': 5, 'purchase': 10}
def on_event(user, cat, type, now):
    s, t = aff.get(user, cat) or (0, now)
    s = s * exp(-(now - t) / TAU) + W[type]   # TAU ~ 3 days
    aff.put(user, cat, (s, now))
